MERGE `{{params.project_name}}.semantics_central.CarContacts` final
USING (
{{range_query}}
) staging
ON final.car_contact_id = staging.car_contact_id
WHEN MATCHED THEN
UPDATE SET    
    final.car_id = staging.car_id,
    final.car_company = staging.car_company,
    final.salutation = staging.salutation,
    final.first_name = staging.first_name,
    final.last_name = staging.last_name,
    final.email = staging.email,
    final.phone = staging.phone,
    final.contact_address = staging.contact_address,
    final.zip = staging.zip,
    final.city = staging.city, 
    final.contact_comment = staging.contact_comment, 
    final.contact_type = staging.contact_type,
    final.contact_subtype = staging.contact_subtype, 
    final.created_at = staging.created_at,
    final.updated_at = staging.updated_at,
    final.deleted_at = staging.deleted_at,
    final.created_by_id = staging.created_by_id,
    final.created_by = staging.created_by,
    final.updated_by_id = staging.updated_by_id,
    final.updated_by = staging.updated_by,
    final.deleted_by_id = staging.deleted_by_id,
    final.deleted_by = staging.deleted_by,
    final.tax_id = staging.tax_id,
    final.bank_account_owner = staging.bank_account_owner,
    final.bank_code = staging.bank_code,
    final.bank_account_number = staging.bank_account_number,
    final.bank_name = staging.bank_name,
    final.account_type = staging.account_type,
    final.bank_account_owner_tax_id = staging.bank_account_owner_tax_id,
    final.bank_account_details = staging.bank_account_details,
    final.occupation = staging.occupation,
    final.marital_status = staging.marital_status,
    final.selling_reason = staging.selling_reason,
    final.referrer_code = staging.referrer_code,
    final.country_id = staging.country_id
WHEN NOT MATCHED THEN
INSERT (
    car_contact_id,
    car_id,
    car_company,
    salutation,
    first_name,
    last_name,
    email,
    phone,
    contact_address,
    zip,
    city, 
    contact_comment, 
    contact_type,
    contact_subtype, 
    created_at,
    updated_at,
    deleted_at,
    created_by_id,
    created_by,
    updated_by_id,
    updated_by,
    deleted_by_id,
    deleted_by,
    tax_id,
    bank_account_owner,
    bank_code,
    bank_account_number,
    bank_name,
    account_type,
    bank_account_owner_tax_id,
    bank_account_details,
    occupation,
    marital_status,
    selling_reason,
    referrer_code,
    country_id
) VALUES (
    staging.car_contact_id, 
    staging.car_id,
    staging.car_company,
    staging.salutation,
    staging.first_name,
    staging.last_name,
    staging.email,
    staging.phone,
    staging.contact_address,
    staging.zip,
    staging.city, 
    staging.contact_comment, 
    staging.contact_type,
    staging.contact_subtype, 
    staging.created_at,
    staging.updated_at,
    staging.deleted_at,
    staging.created_by_id,
    staging.created_by,
    staging.updated_by_id,
    staging.updated_by,
    staging.deleted_by_id,
    staging.deleted_by,
    staging.tax_id,
    staging.bank_account_owner,
    staging.bank_code,
    staging.bank_account_number,
    staging.bank_name,
    staging.account_type,
    staging.bank_account_owner_tax_id,
    staging.bank_account_details,
    staging.occupation,
    staging.marital_status,
    staging.selling_reason,
    staging.referrer_code,
    staging.country_id
)